// Package server wires the audit-service HTTP surface (ADR-0043). The routing
// and ServerInterface are generated by oapi-codegen (gen.go, `task codegen`,
// config oapi-codegen.audit.yaml); this file implements that interface.
//
// Request/response bodies use the hash-stable domain types in internal/audit
// rather than the generated body models: the chained-hash design stores
// `timestamp` verbatim as a string (the generated model maps it to time.Time)
// and the stored event carries an internal `seq`. See oapi-codegen.audit.yaml.
package server

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"

	"github.com/go-chi/chi/v5"

	mw "aireos.local/packages/go/middleware"
	"aireos.local/services/audit-service/internal/audit"
	"aireos.local/services/audit-service/internal/store"
)

// Appender is the narrow slice of *store.Store the handlers need, so tests can
// substitute an in-memory fake without a database.
type Appender interface {
	Append(ctx context.Context, in audit.Ingest) (audit.Event, bool, error)
	Get(ctx context.Context, id string) (audit.Event, error)
	List(ctx context.Context, q store.ListQuery) ([]audit.Event, int64, error)
}

// apiHandlers implements the generated ServerInterface (gen.go).
type apiHandlers struct{ store Appender }

// New returns the audit-service router: the generated chi-server routes wrapped
// in the shared RequireCapability middleware over the service-service /
// human-agent edges (producers fan in over service-service, ADR-0045). v is the
// capability Verifier port; the real PASETO verifier lands in T-008.
func New(s Appender, v mw.Verifier) http.Handler {
	return HandlerWithOptions(&apiHandlers{store: s}, ChiServerOptions{
		BaseRouter:  chi.NewRouter(),
		Middlewares: []MiddlewareFunc{MiddlewareFunc(mw.RequireCapability(v, "service-service", "human-agent"))},
	})
}

// AppendEvent handles POST /v1/events. DisallowUnknownFields rejects a
// client-supplied id/prevHash/chainHash with 400 — a forged-chain attempt
// cannot enter the pipeline.
func (a *apiHandlers) AppendEvent(w http.ResponseWriter, r *http.Request) {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var in audit.Ingest
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return
	}
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return
	}
	e, _, err := a.store.Append(r.Context(), in)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "append failed")
		return
	}
	// 200 for both fresh append and dedup replay (idempotent, ADR-0045).
	writeJSON(w, http.StatusOK, e)
}

// ListEvents handles GET /v1/events with the generated query params.
func (a *apiHandlers) ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams) {
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var afterSeq int64
	if params.Cursor != nil && string(*params.Cursor) != "" {
		n, err := strconv.ParseInt(string(*params.Cursor), 10, 64)
		if err != nil || n < 0 {
			writeError(w, http.StatusBadRequest, "bad_request", "invalid cursor")
			return
		}
		afterSeq = n
	}
	// T-105 is store-layer-only: ListEventsParams is generated from the
	// fragment and does not yet carry direction/filter/preset params (T-106).
	// This call site stays behavior-preserving — ascending, unfiltered, no
	// preset — exactly as before this ticket.
	items, last, err := a.store.List(r.Context(), store.ListQuery{
		Direction: store.Asc,
		Cursor:    afterSeq,
		Limit:     limit,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list failed")
		return
	}
	page := eventPage{Items: items}
	if len(items) == limit { // a full page implies there may be more
		page.Page.NextCursor = strconv.FormatInt(last, 10)
	}
	writeJSON(w, http.StatusOK, page)
}

// GetEvent handles GET /v1/events/{id}.
func (a *apiHandlers) GetEvent(w http.ResponseWriter, r *http.Request, id string) {
	e, err := a.store.Get(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "audit event not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get failed")
		return
	}
	writeJSON(w, http.StatusOK, e)
}

type eventPage struct {
	Items []audit.Event `json:"items"`
	Page  pageMeta      `json:"page"`
}

type pageMeta struct {
	NextCursor string `json:"nextCursor,omitempty"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"code": code, "message": message})
}
